CREATE OR REPLACE VIEW `budjettihaukka-gpt.valtiodata.dim_visualization_metric_v1` AS
SELECT *, '1.0.0' AS contract_version
FROM UNNEST([
  STRUCT('net_accumulation_nominal_eur' AS metric_id, 'Nettokertymä, käyvin hinnoin' AS display_name_fi, 'Valtiokonttorin Nettokertymä-kentän vuosisumma valitulla hierarkiatasolla.' AS definition_fi, 'EUR' AS unit, 'sum' AS aggregation_rule, 'nominal' AS price_basis, 'valtiokonttori_monthly_central_government_finance' AS source_id, 'Lähdejärjestelmän etumerkki säilytetään muuttamattomana.' AS sign_rule, 'Havaintoa ei ole; puuttuva ei tarkoita nollaa.' AS missing_means, ['year', 'fiscal_side', 'hallinnonala', 'kirjanpitoyksikko', 'momentti', 'maararahalaji', 'talousarviotili'] AS supported_dimensions, 'ready' AS visualization_status),
  STRUCT('net_accumulation_real_cpi_eur' AS metric_id, 'Nettokertymä, kiintein hinnoin' AS display_name_fi, 'Nimellinen nettokertymä muunnettuna uusimman saatavilla olevan CPI-vuoden euroiksi.' AS definition_fi, 'EUR' AS unit, 'sum' AS aggregation_rule, 'constant_cpi' AS price_basis, 'valtiokonttori_monthly_central_government_finance' AS source_id, 'Sama kuin nimellisessä nettokertymässä.' AS sign_rule, 'Arvo puuttuu, jos nettokertymä tai hintakerroin puuttuu.' AS missing_means, ['year', 'fiscal_side', 'hallinnonala', 'kirjanpitoyksikko', 'momentti', 'maararahalaji', 'talousarviotili'] AS supported_dimensions, 'ready_with_caveat' AS visualization_status),
  STRUCT('net_accumulation_per_capita_eur' AS metric_id, 'Nettokertymä asukasta kohti' AS display_name_fi, 'Nimellinen nettokertymä jaettuna koko maan keskiväkiluvulla.' AS definition_fi, 'EUR_PER_PERSON' AS unit, 'non_additive' AS aggregation_rule, 'nominal' AS price_basis, 'valtiokonttori_monthly_central_government_finance' AS source_id, 'Sama kuin nimellisessä nettokertymässä.' AS sign_rule, 'Arvo puuttuu, jos nettokertymä tai saman vuoden keskiväkiluku puuttuu.' AS missing_means, ['year', 'fiscal_side', 'hallinnonala', 'kirjanpitoyksikko', 'momentti', 'maararahalaji', 'talousarviotili'] AS supported_dimensions, 'ready' AS visualization_status),
  STRUCT('net_accumulation_pct_gdp' AS metric_id, 'Nettokertymä suhteessa BKT:hen' AS display_name_fi, 'Nimellinen nettokertymä jaettuna saman vuoden käypähintaisella BKT:llä.' AS definition_fi, 'PERCENT' AS unit, 'non_additive' AS aggregation_rule, 'nominal' AS price_basis, 'valtiokonttori_monthly_central_government_finance' AS source_id, 'Sama kuin nimellisessä nettokertymässä.' AS sign_rule, 'Arvo puuttuu, jos nettokertymä tai saman vuoden BKT puuttuu.' AS missing_means, ['year', 'fiscal_side', 'hallinnonala', 'kirjanpitoyksikko', 'momentti', 'maararahalaji', 'talousarviotili'] AS supported_dimensions, 'ready_with_caveat' AS visualization_status),
  STRUCT('original_budget_eur' AS metric_id, 'Alkuperäinen talousarvio' AS display_name_fi, 'Varsinaisen talousarvion momentille osoittama euromäärä.' AS definition_fi, 'EUR' AS unit, 'sum' AS aggregation_rule, 'nominal' AS price_basis, 'vm_budget_documents' AS source_id, 'Määrä esitetään positiivisena; tulo- ja menopuoli erotetaan fiscal_side-kentällä.' AS sign_rule, 'Budjettiriviä ei ole saatavilla; puuttuva ei tarkoita nollaa.' AS missing_means, ['year', 'fiscal_side', 'momentti'] AS supported_dimensions, 'ready' AS visualization_status),
  STRUCT('current_budget_eur' AS metric_id, 'Voimassa oleva talousarvio' AS display_name_fi, 'Alkuperäinen talousarvio ja lisätalousarviot yhteensä.' AS definition_fi, 'EUR' AS unit, 'sum' AS aggregation_rule, 'nominal' AS price_basis, 'vm_budget_documents' AS source_id, 'Määrä esitetään positiivisena; tulo- ja menopuoli erotetaan fiscal_side-kentällä.' AS sign_rule, 'Budjettiriviä ei ole saatavilla; puuttuva ei tarkoita nollaa.' AS missing_means, ['year', 'fiscal_side', 'momentti'] AS supported_dimensions, 'ready' AS visualization_status),
  STRUCT('actual_to_budget_ratio' AS metric_id, 'Toteuma suhteessa budjettiin' AS display_name_fi, 'Vuoden nettokertymä jaettuna voimassa olevalla talousarviolla.' AS definition_fi, 'RATIO' AS unit, 'non_additive' AS aggregation_rule, 'nominal' AS price_basis, 'valtiokonttori_monthly_central_government_finance' AS source_id, 'Suhdeluku lasketaan vain ei-nollaiselle budjetille; lähde-etumerkki säilytetään.' AS sign_rule, 'Toteuma, budjetti tai kelvollinen nimittäjä puuttuu.' AS missing_means, ['year', 'fiscal_side', 'momentti'] AS supported_dimensions, 'ready_with_caveat' AS visualization_status)
])
